import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import type { FrameworkName, ResolvedOptions } from '../types.js';

const HEADER = `/* eslint-disable */
/* AUTO-GENERATED by unplugin-smart-asset. Do not edit. */
/* This file is a build artifact — add it to .gitignore. */
`;

/**
 * Each framework augments a different interface:
 *   React   → react/JSX.IntrinsicElements      (React 19 removed the global JSX namespace)
 *   Preact  → preact/JSX.IntrinsicElements
 *   Solid   → solid-js/JSX.IntrinsicElements
 *   Vue     → vue/GlobalComponents             (read by Volar)
 *   Svelte  → svelte/elements/SvelteHTMLElements (same in v4 and v5)
 * One shared file cannot serve them all, so we emit per detected framework.
 */
export function generateDts(
  keys: string[],
  frameworks: FrameworkName[],
  opts: ResolvedOptions,
): string {
  const tags = [...keys].sort();
  const blocks: string[] = [HEADER];
  const prefix = opts.iconPrefix;

  const jsxFrameworks: Array<[FrameworkName, string, string]> = [
    ['react', 'react', 'SVGProps<SVGSVGElement> & { title?: string }'],
    ['preact', 'preact', 'JSX.SVGAttributes<SVGSVGElement> & { title?: string }'],
    ['solid', 'solid-js', 'JSX.SvgSVGAttributes<SVGSVGElement> & { title?: string }'],
  ];

  for (const [name, moduleName, propType] of jsxFrameworks) {
    if (!frameworks.includes(name)) continue;
    const imports = name === 'react'
      ? `import type { SVGProps } from 'react';`
      : `import type { JSX } from '${moduleName}';`;
    const entries = tags.map((k) => `      '${prefix}-${k}': ${propType};`).join('\n');
    const wildcard = opts.allowUnknownIcons
      ? `\n      [key: \`${prefix}-\${string}\`]: ${propType};`
      : '';
    blocks.push(`${imports}

declare module '${moduleName}' {
  namespace JSX {
    interface IntrinsicElements {
${entries}${wildcard}
    }
  }
}
`);
  }

  if (frameworks.includes('vue')) {
    const entries = tags.map((k) => `    '${prefix}-${k}': Component;`).join('\n');
    const wildcard = opts.allowUnknownIcons
      ? `\n    [key: \`${prefix}-\${string}\`]: Component;`
      : '';
    blocks.push(`import type { Component } from 'vue';

declare module 'vue' {
  interface GlobalComponents {
${entries}${wildcard}
  }
}
`);
  }

  if (frameworks.includes('svelte')) {
    const entries = tags.map((k) => `    '${prefix}-${k}': HTMLAttributes<SVGSVGElement>;`).join('\n');
    const wildcard = opts.allowUnknownIcons
      ? `\n    [key: \`${prefix}-\${string}\`]: HTMLAttributes<SVGSVGElement>;`
      : '';
    blocks.push(`import type { HTMLAttributes } from 'svelte/elements';

declare module 'svelte/elements' {
  interface SvelteHTMLElements {
${entries}${wildcard}
  }
}
`);
  }

  return blocks.join('\n');
}

/** Write only when the content changed — avoids a tsc --watch feedback loop. */
export function writeDtsIfChanged(file: string, content: string): boolean {
  if (existsSync(file)) {
    try {
      if (readFileSync(file, 'utf8') === content) return false;
    } catch {
      /* fall through and rewrite */
    }
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
  return true;
}
